  "helpCoopDashStep1": "মূল মেট্রিক্স নিরীক্ষণ করুন: মোট পণ্য মূল্য (GMV), সক্রিয় কর্মীর ব্যবহার, সম্পন্ন কাজ এবং বিশ্বাস রেটিং।",
  "helpCoopDashStep2": "আয়, ব্যয় এবং নগদ প্রবাহের ইন্টারেক্টিভ চার্ট দেখুন (বার, লাইন, এরিয়া)।",
  "helpCoopDashStep3": "রিয়েল-টাইম নগদ তারল্য এবং ৩০ দিনের আর্থিক পরিস্থিতি পরীক্ষা করুন।",
  "helpCoopDashTitle": "নির্বাহী ড্যাশবোর্ড এবং আর্থিক পর্যালোচনা",
  "helpCoopDemandDesc": "মৌসুমি এবং জেলাভিত্তিক শ্রম চাহিদার পূর্বাভাস।",
  "helpCoopDemandStep1": "সেবা চাহিদার পূর্বাভাস প্রদানকারী মেশিন লার্নিং মডেলগুলি পরীক্ষা করুন।",
  "helpCoopDemandStep2": "নির্দিষ্ট ট্রেডে আসন্ন ঘাটতি চিহ্নিত করুন (যেমন: গ্রীষ্মে এসি মেরামত, উৎসবের আগে পেইন্টিং)।",
  "helpCoopDemandStep3": "চাহিদা বৃদ্ধির আগে কর্মী অনবোর্ডিং এবং দক্ষতা প্রশিক্ষণ সূচি পরিকল্পনা করুন।",
  "helpCoopDemandTitle": "AI চাহিদা পরিকল্পনা এবং বৃদ্ধি পূর্বাভাস",
  "helpCoopDispatchDesc": "রিয়েল-টাইম সেবা বরাদ্দ পর্যবেক্ষণ করুন এবং জরুরি SOS সতর্কতায় সাড়া দিন।",
  "helpCoopDispatchStep1": "সক্রিয় কাজ এবং কর্মীদের লাইভ অগ্রগতি ট্র্যাক করতে জিপিএস ম্যাপ দেখুন।",
  "helpCoopDispatchStep2": "জরুরি সহায়তার জন্য লাল রঙের জরুরি SOS সতর্কতাগুলি পর্যবেক্ষণ করুন।",
  "helpCoopDispatchStep3": "যানজট বা বিলম্ব হলে অন্যান্য কর্মীদের কাজ পুনর্বণ্টন করুন।",
  "helpCoopDispatchTitle": "ভৌগোলিক প্রেরণ ও বহর ম্যাট্রিক্স",
  "helpCoopFinDesc": "স্বচ্ছ ৫% সমবায় ফি, ৯৫% সরাসরি মজুরি এবং জালিয়াতি শনাক্তকরণ ব্যবস্থা।",
  "helpCoopFinStep1": "ক্রিপ্টোগ্রাফিক অডিট রেকর্ড এবং সুরক্ষিত ব্যাংক স্থানান্তর পরীক্ষা করুন।",
  "helpCoopFinStep2": "AI দ্বারা চিহ্নিত অস্বাভাবিক বিলিং বা সম্ভাব্য অসঙ্গতিগুলি পর্যালোচনা করুন।",
  "helpCoopFinStep3": "কর্মী বীমা এবং জরুরি অগ্রিম অর্থ প্রদানকারী কল্যাণ তহবিল পরিচালনা করুন।",
  "helpCoopFinTitle": "আর্থিক ও AI অসঙ্গতি শনাক্তকরণ",
  "helpCoopHowItWorksDesc": "সমবায় অ্যাডমিন পোর্টাল হলো ফেডারেশনের কেন্দ্রীয় নিয়ন্ত্রণ ব্যবস্থা। কর্মীর পরিচয় যাচাই, স্বয়ংক্রিয় প্রেরণ এবং ন্যায্য মজুরি নিশ্চিত করতে প্রশাসকরা এটি ব্যবহার করেন।",
  "helpCoopWorkersDesc": "সদস্য-কর্মীদের কেওয়াইসি যাচাই করুন এবং ট্রেড দক্ষতা অনুমোদন করুন।",
  "helpCoopWorkersStep1": "কর্মী তালিকা 'সমস্ত', 'যাচাইকরণ বাকি' বা 'যাচাইকৃত' অনুযায়ী ফিল্টার করুন।",
  "helpCoopWorkersStep2": "আপলোড করা আধার কার্ড, দক্ষতা শংসাপত্র এবং ব্যাংক বিবরণ পর্যালোচনা করুন।",
  "helpCoopWorkersStep3": "কর্মী দক্ষতা পরিবর্তনের অনুরোধ করলে পর্যালোচনা করে 'অনুমোদন ও যাচাই করুন' ক্লিক করুন।",
  "helpCoopWorkersStep4": "নিরাপত্তা নিয়ম অমান্যকারী কর্মীদের সাময়িক বরখাস্ত বা পর্যালোচনা করুন।",
  "helpCoopWorkersTitle": "কর্মী যাচাইকরণ এবং দক্ষতা অনুমোদন",
  "helpEmergencyHelp": "জরুরি সহায়তা প্রয়োজন: যেকোনো বিপদ বা দুর্ঘটনার ক্ষেত্রে অবিলম্বে SOS বোতাম ব্যবহার করুন।",
  "helpHouseholdBannerDesc": "যাচাইকৃত সমবায় কর্মীদের বুক করতে, স্বচ্ছ রেট বুঝতে এবং নিরাপদ পেমেন্টের জন্য সম্পূর্ণ নির্দেশিকা।",
  "helpHouseholdBookDesc": "Schedule a certified tradesperson matched by proximity, craft rating, and verified skills.",
  "helpHouseholdBookStep1": "নির্বাচন করুন",
  "helpHouseholdBookStep2": "2. Enter Details: Type your service address, preferred date and time slot, and special instructions.",
