  "helpHouseholdBookTitle": "শ্রমিক",
  "helpHouseholdBookingDesc": "मानक पारदर्शी दरों पर केवल 3 चरणों में प्रमाणित कारीगरों को बुक करें।",
  "helpHouseholdBookingStep1": "अपनी आवश्यक सेवा (प्लंबिंग, इलेक्ट्रिकल, पेंटिंग, सफाई आदि) चुनें और कार्य का दायरा निर्दिष्ट करें।",
  "helpHouseholdBookingStep2": "पारदर्शी दर विवरण की समीक्षा करें: कुल राशि का 95% सीधे श्रमिक को जाता है और केवल 5% सहकारी संचालन में जाता है।",
  "helpHouseholdBookingStep3": "पसंदीदा समय स्लॉट और अपना पता चुनें। निकटतम उपलब्ध प्रमाणित कारीगर को स्वचालित रूप से आवंटित किया जाएगा।",
  "helpHouseholdBookingTitle": "सेवा बुक करना और पारदर्शी मूल्य निर्धारण",
  "helpHouseholdBookingsDesc": "Track live worker arrival, manage security OTPs, and rate service quality.",
