  "helpHouseholdFeatDisputeDesc": "श्रम अधिकारियों के साथ त्वरित और निष्पक्ष विवाद समाधान।",
  "helpHouseholdFeatDisputeTitle": "सुरक्षित मध्यस्थता",
  "helpHouseholdFeatFairDesc": "श्रमिक को 95% सीधा भुगतान और पारदर्शी 5% सहकारी शुल्क।",
