  "helpWorkerFairWageDesc": "कोई बिचौलिया कटौती नहीं: आपकी कमाई का 95% सीधे आपके बैंक खाते में जाता है।",
  "helpWorkerFairWageStep1": "ग्राहक द्वारा भुगतान करते ही 95% राशि तुरंत आपके बैंक/UPI में जमा हो जाती है।",
  "helpWorkerFairWageStep2": "केवल 5% राशि सहकारी मंच रखरखाव और कल्याण कोष के लिए रखी जाती है।",
  "helpWorkerFairWageStep3": "अपने डैशबोर्ड पर दैनिक कमाई और विस्तृत वेतन पर्ची कभी भी देखें।",
