  "helpWorkerFeatDashDesc": "দৈনিক সারাংশ এবং দ্রুত পদক্ষেপের জন্য মূল পর্দা।",
  "helpWorkerFeatDashStep1": "আজকের আয়, সম্পন্ন কাজ, রেটিং এবং কল্যাণ তহবিলের স্থিতি এক নজরে দেখুন।",
  "helpWorkerFeatDashStep2": "শীর্ষ কার্ডে আপনার পরবর্তী কাজ সরাসরি দেখুন।",
  "helpWorkerFeatDashStep3": "सक्रिय कार्य, भुगतान इतिहास या कल्याण योजना पर जाने के लिए त्वरित बटन का उपयोग करें।",
