  "helpWorkerFeatEarningsStep2": "See the transparent 100% wage breakdown — zero platform commission taken.",
  "helpWorkerFeatEarningsStep3": "सामूहिक कल्याण कोष में अपना 2% योगदान देखें जो आपके बीमा को कवर करता है।",
