  "helpWorkerFeatJobsDesc": "কাজের অনুরোধ গ্রহণ, পরিচালনা এবং সম্পন্ন করার স্থান।",
  "helpWorkerFeatJobsStep1": "দেখুন",
  "helpWorkerFeatJobsStep2": "2. कार्य स्वीकार करें: कार्य करने की पुष्टि के लिए 'कार्य स्वीकार करें' पर क्लिक करें।",
  "helpWorkerFeatJobsStep3": "3. रास्ते में हूँ: जब आप निकलें तो ग्राहक को सूचित करने के लिए क्लिक करें।",
  "helpWorkerFeatJobsStep4": "4. Start Work (OTP Required): When you reach the customer’s house, ask them for their 4-digit Job Start OTP and enter it in the app to start the timer.",
  "helpWorkerFeatJobsStep5": "5. पूर्ण चिह्नित करें: पूरा होने पर भुगतान सीधे आपके वेज लेजर में आ जाएगा।",
  "helpWorkerFeatJobsTitle": "সক্রিয় কাজ ও জীবনচক্র",
  "helpWorkerFeatLearningDesc": "নতুন দক্ষতা ও সুরক্ষা পদ্ধতি শিখুন।",
  "helpWorkerFeatLearningStep1": "छोटे, व्यावहारिक वीडियो पाठ और शिल्प ट्यूटोरियल देखें।",
  "helpWorkerFeatLearningStep2": "अपने ज्ञान का परीक्षण करने के लिए प्रत्येक पाठ के बाद प्रश्नोत्तरी लें।",
  "helpWorkerFeatLearningStep3": "उच्च वेतन वाले कार्यों में प्राथमिकता पाने के लिए कौशल प्रमाण पत्र अर्जित करें।",
  "helpWorkerFeatLearningTitle": "দক্ষতা বৃদ্ধি অ্যাকাডেমি",
  "helpWorkerFeatProfileDesc": "আপনার পেশা এবং অভিজ্ঞতা পরিচালনা করুন।",
  "helpWorkerFeatProfileStep1": "अपनी प्राथमिक ट्रेड को अपडेट करने के लिए 'ट्रेड संपादित करें' पर क्लिक करें।",
  "helpWorkerFeatProfileStep2": "वर्षों और महीनों में अपना सटीक अनुभव सेट करें।",
  "helpWorkerFeatProfileStep3": "When you save a new trade, your profile will show \"⏳ Verification in Progress\" until the cooperative admin reviews and approves your credentials.",
  "helpWorkerFeatProfileStep4": "Once approved, your profile will display \"✓ Verified\", helping you get more job matches.",
  "helpWorkerFeatProfileTitle": "দক্ষতা প্রোফাইল ও যাচাইকরণ",
  "helpWorkerFeatSosDesc": "দুর্ঘটনা বা বিপদের জন্য তাৎক্ষণিক সহায়তা।",
  "helpWorkerFeatSosStep1": "জরুরি সেবা",
  "helpWorkerFeatSosStep2": "নির্বাচন করুন",
  "helpWorkerFeatSosStep3": "सुरक्षा अधिकारी द्वारा आपके लाइव जीपीएस स्थान को तुरंत प्राथमिकता दी जाएगी।",
  "helpWorkerFeatSosTitle": "জরুরি দ্রুত প্রতিক্রিয়া (SOS)",
  "helpWorkerFeatWelfareDesc": "সমবায় প্রদত্ত সামাজিক ও চিকিৎসা সুরক্ষা পান।",
  "helpWorkerFeatWelfareStep1": "अपनी दुर्घटना और स्वास्थ्य बीमा पॉलिसी की सक्रिय स्थिति देखें।",
  "helpWorkerFeatWelfareStep2": "দেখুন",
  "helpWorkerFeatWelfareStep3": "जरूरत पड़ने पर आपातकालीन चिकित्सा अग्रिम के लिए आवेदन करें।",
  "helpWorkerFeatWelfareTitle": "কল্যাণ ও বীমা কভারেজ",
  "helpWorkerJobsDesc": "सक्रिय कार्य कतार प्रबंधित करें, कार्य स्थिति अपडेट करें और डिजिटल चालान उत्पन्न करें।",
  "helpWorkerJobsStep1": "सक्रिय कार्यों की सूची देखें और अपनी प्राथमिकता तय करें।",
  "helpWorkerJobsStep2": "ग्राहक के स्थान पर पहुंचने पर 'पहुंच गए' स्थिति अपडेट करें।",
  "helpWorkerJobsStep3": "काम पूरा होने के बाद डिजिटल चालान तैयार करें और ग्राहक से अनुमोदन लें।",
  "helpWorkerJobsTitle": "कार्य कतार और चालान",
  "helpWorkerLearningDesc": "Help Worker Learning Desc",
  "helpWorkerLearningTitle": "Help Worker Learning Title",
  "helpWorkerOtpDesc": "काम शुरू करने के लिए सुरक्षित OTP सत्यापन और कार्य समापन प्रक्रिया।",
  "helpWorkerOtpStep1": "ग्राहक के पते पर पहुंचकर काम शुरू करने से पहले 4-अंकों का OTP दर्ज करें।",
  "helpWorkerOtpStep2": "काम पूरा होने के बाद 'कार्य पूर्ण' पर क्लिक करें और अंतिम विवरण भरें।",
  "helpWorkerOtpStep3": "ग्राहक को डिजिटल चालान प्राप्त होगा और वे भुगतान करेंगे।",
