  "helpWorkerSocialSecurityDesc": "दुर्घटना बीमा, स्वास्थ्य लाभ और पेंशन योजनाओं के लिए स्वचालित कवरेज।",
  "helpWorkerSocialSecurityStep1": "हर कार्य के साथ प्रधानमंत्री सुरक्षा बीमा योजना (PMSBY) स्वचालित रूप से सक्रिय रहती है।",
  "helpWorkerSocialSecurityStep2": "सहकारी महासंघ अटल पेंशन योजना (APY) में 50% मैचिंग योगदान देता है।",
  "helpWorkerSocialSecurityStep3": "आपातकालीन चिकित्सा अग्रिम या कल्याण लाभों के लिए सीधे पोर्टल से दावा करें।",
