  "workerHowItWorksDesc": "সহকার কানেক্ট কর্মী পোর্টাল কোনো মধ্যস্বত্বভোগী ছাড়াই আপনাকে সরাসরি নিকটবর্তী গ্রাহকদের সাথে সংযুক্ত করে। আপনি কাজের অনুরোধ গ্রহণ করতে পারেন, সুরক্ষিত ওটিপি দিয়ে কাজের সূচনা করতে পারেন, তাত্ক্ষণিকভাবে আপনার লেজারে মজুরি পেতে পারেন এবং সমবায় সামাজিক সুরক্ষা সুবিধা ভোগ করতে পারেন।",
